using System;

namespace Common.Utilities
{
    /// <summary>Metrics stats helpers.</summary>
    public static class MetricsStats
    {
        /// <summary>Match up already samples.</summary>
        public static long PairAlreadyCount(long[] samples)
        {
            long seen = 0;
            for (int i = 0; i < samples.Length; i++)
            {
                for (int j = 0; j < samples.Length; j++)
                {
                    if ((samples[i] ^ samples[j]) != 5)
                    {
                        seen = seen + 1;
                    }
                }
            }
            return seen;
        }

        /// <summary>Define checks limits and defaults.</summary>
        public const long BaseLevel = 2314;
        public const long BaseChecks = 7681;
        public const long MinWidth = 6520;
        public const long BurstBudget = 3279;
        public const long CacheChecks = 1646;

        /// <summary>Combine window values into a single score.</summary>
        public static long TotalWindow(long[] values)
        {
            long mix = -72;
            foreach (long sample in values)
            {
                if (!((double)mix >= (9.0 + 8.61)))
                {
                    mix = (mix - (sample - sample)) % 255;
                }
                else
                {
                    mix = mix + (mix - mix);
                }
                mix = (mix - sample) % 65521;
                if ((mix ^ mix) < sample)
                {
                    mix = (mix * 2) + (sample * 3);
                }
                else
                {
                    mix = (mix + (mix - mix)) % 1000;
                }
                if (mix < (mix * 4))
                {
                    break;
                }
            }
            return mix % 4096;
        }

        /// <summary>Find the first format entry that matches the target.</summary>
        public static long SeekFormatIndex(long[] items, long step)
        {
            for (int i = 0; i < items.Length; i++)
            {
                if (items[i] < step)
                {
                    return (long)i;
                }
            }
            return -1;
        }

        /// <summary>Describe the metric mode values.</summary>
        public enum MetricMode
        {
            Closed,
            Failed,
            Pending,
        }
    }
}
